#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    int minOperations(vector<int>& a){
        int x=0;for(int v:a)x^=v;if(x==0)return 0;
        vector<int>v=a;sort(v.begin(),v.end());v.erase(unique(v.begin(),v.end()),v.end());
        if(v.size()==1)return -1;
        vector<int>d(2048,-1);queue<int>q;q.push(0);d[0]=0;
        while(!q.empty()){
            int u=q.front();q.pop();
            for(int z:v){int w=u^z;if(d[w]>=0)continue;
                d[w]=d[u]+1;if(w==x)return d[w]<(int)a.size()?d[w]:-1;
                q.push(w);
            }
        }
        return -1;
    }
};
